// mcx0 t04: the binding effect ledger (BindingInfo::effect / consumer, generated by engine/lua/tools/gen_bindings.py).
//   * every Recorded binding has a consumer in alamo_game, or is in kUnconsumed below: the recorded-but-never-shown
//     gaps of docs/MOD_COMPAT_DESIGN.md §9.1 that roadmap group mcx6 closes. The list may only shrink: a binding that
//     gains a consumer must leave it (the test fails on a stale entry), and a new recorded binding needs a consumer;
//   * NoopGap / NoopRetail / Partial rows cite their reason; binding_effect_gap() matches the rule.
#include <algorithm>
#include <array>
#include <iterator>
#include <string>
#include <string_view>
#include <vector>

#include "alamo/lua/bindings.hpp"
#include "alamo/lua/object_bridge.hpp"
#include "alamo/test/support.hpp"

using namespace alamo::lua;
using ::alamo::test::g_fail;

namespace {

// mcx6 t05 emptied it (the cinematic bindings, docs/re/MCX6_T05_CINEMATIC_BINDINGS.md); it stays as the ratchet.
constexpr std::array<std::string_view, 0> kUnconsumed{};

std::string key_of(const BindingInfo& b) {
    return b.kind == BindingKind::Global ? std::string(b.name) : std::string(b.cls) + "." + b.name;
}

}  // namespace

int main() {
    size_t recorded = 0, gaps = 0, listed_seen = 0;
    for (const BindingInfo& b : binding_table()) {
        const std::string k = key_of(b);
        const bool listed = std::find(kUnconsumed.begin(), kUnconsumed.end(), k) != kUnconsumed.end();
        CHECK(b.consumer != nullptr);
        if (b.effect == BindingEffect::Recorded) {
            ++recorded;
            const bool has = b.consumer[0] != '\0';
            if (!has && !listed) std::printf("recorded binding without a consumer in alamo_game: %s\n", k.c_str());
            if (has && listed) std::printf("listed as unconsumed but has a consumer now (drop it from kUnconsumed): %s\n", k.c_str());
            CHECK(has != listed);
            if (listed) ++listed_seen;
        } else if (b.effect != BindingEffect::Full) {
            CHECK(b.consumer[0] != '\0');  // the annotation's spec or reason
            CHECK(!listed);
        } else {
            CHECK(!listed);
        }
        if (binding_effect_gap(b)) ++gaps;
        CHECK(binding_effect_gap(b) == ((b.effect == BindingEffect::Recorded && b.consumer[0] == '\0') ||
                                        b.effect == BindingEffect::NoopGap || b.effect == BindingEffect::Partial));
    }
    CHECK(listed_seen == kUnconsumed.size());
    CHECK(recorded >= 60);
    std::printf("bindings: %zu recorded, %zu with an effect gap\n", recorded, gaps);
    CHECK(std::string_view(to_string(BindingEffect::NoopRetail)) == "noop-retail");

    // ref5 t04: the hook ledger. Every hook a row names is in the hook table; Get_Name reads ship_name; a set with the hook
    // wired no longer lists it (the host test, alamo_sim_battle_story_tests, feeds the real bridges).
    size_t with_hooks = 0;
    const auto known = [](std::string_view q) {
        for (const BridgeHookInfo& h : bridge_hook_table())
            if (q == std::string(h.bridge) + "." + h.name) return true;
        return false;
    };
    for (const BindingInfo& b : binding_table()) {
        std::string_view rest(b.hooks);
        with_hooks += rest.empty() ? 0u : 1u;
        while (!rest.empty()) {
            const size_t sp = rest.find(' ');
            CHECK(known(rest.substr(0, sp)));
            rest = sp == std::string_view::npos ? std::string_view() : rest.substr(sp + 1);
        }
    }
    CHECK(with_hooks > 30 && bridge_hook_table().size() > 80);
    const auto lists_get_name = [](const std::vector<std::string>& v) {
        return std::find(v.begin(), v.end(), "GameObjectWrapper.Get_Name reads ObjectBridge.ship_name") != v.end();
    };
    ObjectBridge bridge;
    BridgeHookSets sets;
    sets.objects.push_back(&bridge);
    CHECK(lists_get_name(unwired_full_binding_hooks(sets)) && !bridge_hook_wired(sets, "ObjectBridge.ship_name"));
    bridge.ship_name = [](alamo::objects::ObjectHandle) { return std::string_view("\"Avenger\""); };
    CHECK(!lists_get_name(unwired_full_binding_hooks(sets)) && bridge_hook_wired(sets, "ObjectBridge.ship_name"));
    CHECK(!bridge_hook_wired(sets, "ObjectBridge.no_such_hook"));
    std::printf("bindings: %zu read bridge hooks\n", with_hooks);
    return ::alamo::test::report("alamo_lua_binding_effects_tests");
}
